#include <iostream>
#include <cstdlib>

void	ft_ABC(int **n, char **order)
{
	int		*pN;
	char	*pO;
	int		tmp;

	pN = *n;
	pO = *order;
	while (*pO)
	{
		if (*pN > *(pN + 1))
		{
			tmp = *pN;
			*pN = *(pN + 1);
			*(pN + 1) = tmp;
		}
		if (*(pN + 1) > *(pN + 2))
		{
			tmp = *(pN + 1);
			*(pN + 1) = *(pN + 2);
			*(pN + 2) = tmp;
		}
		if (*pN > *(pN + 1))
		{
			tmp = *pN;
			*pN = *(pN + 1);
			*(pN + 1) = tmp;
		}
		if (*pO == 'A')
			std::cout << *pN;
		else if (*pO == 'B')
			std::cout << *(pN + 1);
		else if (*pO == 'C')
			std::cout << *(pN + 2);
		if (*(pO + 1))
			std::cout << " ";
		pO++;
	}
	std::cout << "\n";
}

int	main(void)
{
	int		*nbr;
	char	*str;

	nbr = (int *)malloc(sizeof(*nbr) * 3);
	str = (char *)malloc((sizeof(*str) * 3) + 1);
	if (!nbr || !str)
	{
		std::cout << "Malloc ha fallado" << "\n";
		free(nbr);
		free(str);
		return (1);
	}
	*(str + 3) = '\0';
	if (std::cin >> *nbr >> *(nbr + 1) >> *(nbr + 2) >> *str >> *(str + 1) >> *(str + 2))
		ft_ABC(&nbr, &str);
	free(nbr);
	free(str);
	nbr = nullptr;
	str = nullptr;
	return (0);
}
